        "questionIntent": "조회 지연의 원인에 맞는 개선 방법을 선택했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회가 느렸던 상황",
          "task": "조회 병목에 적합한 개선 방법을 정하는 일",
          "action": "실행 계획이나 조회 구조에서 확인한 병목을 근거로 개선 방법을 선택한 판단",
          "result": "개선 전후 측정 결과는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "개선 방법을 선택한 근거",
          "실행 계획이나 조회 구조에서 확인한 병목의 구체적인 모습",
          "선택한 방법이 해당 병목을 줄이는 이유"
        ]
      },
      "question": "포켓마켓에서 운영 화면의 신고 목록 조회 속도를 개선하셨네요. 병목을 줄일 개선 방법은 어떤 근거로 정하셨나요?",
      "answerTip": "당시 판단을 중심으로 이야기해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "답변에 실행 계획이나 조회 구조에서 확인한 구체적인 병목이 드러난다.",
            "답변에 선택한 개선 방법과 그 방법이 해당 병목을 줄이는 이유가 연결되어 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "답변에 개선 방법을 선택한 근거는 드러나지만, 관찰한 병목이 구체적이지 않거나 해당 방법과의 연결이 약하다."
          ]
        },
        "poor": {
          "criteria": [
            "답변에 개선 방법이나 속도 변화만 드러나고, 그 방법을 선택한 근거는 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 확인한 장애 원인을 바탕으로 복구와 재발 방지를 고려해 대응 방안을 정했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 알림이 중복 발송된 상황",
          "task": "장애 원인에 맞는 대응 방안을 정하는 일",
          "action": "로그에서 확인한 원인을 근거로 당장의 중복 발송을 막는 조치와 재발을 막는 조치의 목적을 구분한 판단",
          "result": "대응 이후 재발 여부는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "장애 대응 방안을 정한 기준",
          "로그에서 확인한 원인과 대응 방안의 연결",
          "당장의 복구와 재발 방지를 구분한 판단"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 수정하셨네요. 같은 장애가 반복되지 않도록 장애 대응 방안은 어떤 기준으로 정하셨나요?",
      "answerTip": "본인이 내린 판단을 중심으로 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "답변에 로그로 확인한 장애 원인과 대응 방안을 연결한 기준이 드러난다.",
            "답변에 당장의 중복 발송을 막는 조치와 같은 장애의 재발을 막는 조치의 목적 차이가 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "답변에 장애 대응 방안을 정한 기준은 드러나지만, 로그로 확인한 원인과의 연결이나 복구와 재발 방지의 구분이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "답변에 오류를 수정했다는 내용만 드러나고, 대응 방안을 정한 기준이나 장애 원인과의 연결은 드러나지 않는다."
          ]
        }
      }
    }
  ]
}

