          ]
        },
        "poor": {
          "criteria": [
            "답변에 인터뷰 내용을 정리했다는 설명만 있고 요구사항으로 구체화한 기준은 드러나지 않는다.",
            "답변에 요청의 목적과 구현 범위를 연결한 판단이 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능 흐름과 예외 상황을 구현 가능한 화면 단위로 설계한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성한 상황",
          "task": "개발자와 디자이너가 기능 동작을 이해할 수 있도록 화면 흐름과 예외 상황을 설계하는 일",
          "action": "실제 기능을 바탕으로 화면 간 이동, 화면별 상태 변화, 예외 상황의 안내를 설계한 기준을 설명한다.",
          "result": "구현 과정에서의 활용 결과는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "기능 흐름과 예외 상황을 화면 단위로 설계한 기준",
          "실제 기능에서 화면 간 이동과 상태 변화를 구분한 근거",
          "예외 상황에 따른 화면 동작과 안내를 설계에 담은 기준"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨네요. 어떤 기준으로 기능 흐름과 예외 상황을 화면 단위로 설계하셨나요?",
      "answerTip": "한 기능을 예로 들면 설명이 쉬워져요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "답변에 실제 기능을 예로 들어 기능 흐름과 예외 상황을 화면 단위로 설계한 기준이 드러난다.",
            "답변에 사용자 행동에 따른 화면 간 이동과 상태 변화를 구분한 근거가 드러난다.",
            "답변에 예외 상황의 화면 동작과 안내를 개발자·디자이너가 이해할 수 있도록 설계한 기준이 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "답변에 기능 흐름과 예외 상황의 설계 기준은 드러나지만 실제 화면에 적용한 설명이 부족하다.",
            "답변에 화면 간 이동, 상태 변화, 예외 상황의 안내 중 일부의 설계 근거만 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "답변에 화면 수나 도구 사용 설명만 있고 기능 흐름과 예외 상황의 설계 기준은 드러나지 않는다.",
            "답변에 화면의 시각적 배치만 드러나고 기능 동작이나 상태 변화를 설계한 판단은 드러나지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "진통제 처방에서 어떤 근거로 투약을 멈추고 확인해야 한다고 판단했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방을 받고 투약을 준비했던 상황",
          "task": "처방 용량을 그대로 투여해도 되는지 판단해야 했음",
          "action": "처방 용량과 환자의 기존 투약 정보 등 실제 확인한 사실을 근거로 담당의의 확인이 필요하다고 판단함",
          "result": "확인 이후의 경과는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "처방 용량에 확인이 필요하다고 판단한 근거",
          "처방 용량의 차이를 알아차리는 데 사용한 구체적인 환자 정보나 투약 정보",
          "해당 차이를 확인 없이 투약해서는 안 된다고 본 이유"
        ]
      },
      "question": "수술 후 환자의 진통제 투약을 멈추셨던 경험이 있으시네요. 무엇을 근거로 처방 용량에 확인이 필요하다고 판단하셨나요?",
      "answerTip": "당시 확인했던 사실을 중심으로 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "답변에 처방 용량의 이상을 판단하는 데 사용한 구체적인 환자 정보나 투약 정보가 드러난다.",
            "답변에 그 정보가 투약을 멈추고 처방을 확인해야 할 근거가 되는 이유가 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "답변에 평소 용량과 달라 확인이 필요했다는 근거는 드러나지만, 비교한 정보나 확인 없이 투약해서는 안 되는 이유가 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "답변에 투약을 멈추거나 담당의에게 확인했다는 행동만 드러나고, 처방 용량을 의심한 근거는 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태 변화를 기록과 인수인계에 반영하는 기준이 간호의 연속성과 연결되는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "낙상 고위험 환자 인수인계 체크리스트 개선에 참여했던 상황",
          "task": "다음 근무자가 환자 상태 변화를 놓치지 않도록 기록과 인수인계에 반영할 기준을 정해야 했음",
          "action": "관찰된 상태 변화와 환자 안전에 미치는 영향을 근거로 기록과 인수인계에 반영하는 기준을 설명함",
          "result": "기록과 인수인계 이후의 경과는 꼬리질문에서 확인"
        },
        "expectedEvidence": [
          "환자 상태 변화를 기록과 인수인계에 반영한 기준",
          "그 기준을 적용한 구체적인 관찰 정보나 상태 변화",
          "해당 변화가 다음 근무자의 관찰이나 간호에 중요하다고 본 이유"
        ]
      },
      "question": "낙상 고위험 환자 인수인계 체크리스트 개선에 참여하셨네요. 환자 상태 변화를 어떤 기준으로 기록과 인수인계에 반영하셨나요?",
      "answerTip": "당시의 판단을 중심으로 차분히 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "답변에 구체적인 관찰 정보나 상태 변화를 바탕으로 기록과 인수인계에 반영한 기준이 드러난다.",
            "답변에 해당 변화가 다음 근무자의 환자 관찰이나 안전한 간호에 중요한 이유가 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "답변에 상태 변화의 중요도나 간호 필요성에 따라 반영했다는 기준은 드러나지만, 실제 관찰 정보나 다음 근무자의 간호와의 연결이 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "답변에 체크리스트에 추가한 항목이나 개선 성과만 드러나고, 환자 상태 변화를 기록과 인수인계에 반영한 기준은 드러나지 않는다."
          ]
        }
      }
    }
  ]
}

